    # Pi value
    # 0 references
    proc Pi {} {
        return [expr {acos(-1)}]
    }
    # 0 references
    proc deg2rad {deg} {
        return [expr {$deg * Pi() / 180.0}]
    }
}

set pi2 [expr {Pi() / 2.0}]
set rad [expr {deg2rad(45)}]
```
Even though it works without an affiliation, it finds **one** reference for each call:
```tcl
